mutants.mutated:
const { state: dataHealth, retry } = useDataHealth();
const seen = retry as unknown as { attention?: unknown };
if (seen.attention !== attention) {
  seen.attention = attention;
  if (attention.kind === "ok") queueMicrotask(retry);
}

mutants.original:
{showNeedsFixing && <NeedsFixing dataHealth={dataHealth} onReread={retry} />}
<div className="grid grid-cols-2 items-start gap-5">
  {showRecent && <RecentDownloads />}
  {showFollow && <WhatYouFollow />}
</div>
